"""This function returns the nth Fibonacci number."""
def fib(n: Any) -> object {
    i = 0;
    j = 1;
    n = n - 1;
    while (n >= 0) {
        (i, j) = (j, (i + j));
        n = n - 1;
    }
    return i;
}

"""
    Returns the year, month, day of the next day.
    Simple version: assume every month has 30 days.
    """
def nextDay(year: Any, month: Any, day: Any) -> object {
    years = year;
    months = month;
    days = day + 1;
    if (days > 30) {
        days = 1;
        months = month + 1;
        if (months > 12) {
            months = 1;
            years = year + 1;
        }
    }
    return (years, months, days);
}

